-- USER_PASSWORD is a bcrypt hash of 'abcd'. ON CONFLICT DO UPDATE (not DO NOTHING) so this
-- seed is corrective for rows already in a PVC-backed local Postgres from before bcrypt was
-- introduced -- otherwise the plaintext row would silently survive and fail login.
INSERT INTO DIGITAL_SERVICE_USER(USER_ID, USER_NAME, USER_PASSWORD, PHONE_NUMBER) VALUES(199999, 'JOHN DOE', '$2a$10$XHzy0W9Hwu2M6fys7aTYMu.elgxDeIjKteetdyXE8WcoHeglH46Ri', '+17037550417') ON CONFLICT (USER_ID) DO UPDATE SET USER_PASSWORD = EXCLUDED.USER_PASSWORD;
